{
  "key": "pr-834",
  "fields": {
    "summary": "fix(comments): render the branch name inline, not as a fenced block",
    "description": "Fixes #820. `m.code(branchName)` is a fenced block on the markdown flavor, so the branch landed on its own lines in ADO/GitHub comments. Switched to `m.inline()` in the 5 scripts that print it; Jira renders inline as before. Test added so `code()` is not used for branch names again. Suite 2367 passed."
  }
}

