/**
 * Unit tests for common/commentMarkup.js.
 *
 * Uses: loadModule(), assert, test(), suite()
 */
/* global loadModule, assert, test, suite */

suite('commentMarkup', function () {

    // Single owner of the GitHub key-shape convention (gh-770) — flavor
    // detection must derive from it, so the loader wires the real module.
    var ticketKeyShapesModule = loadModule('js/common/ticketKeyShapes.js');
    var commentMarkup = loadModule('js/common/commentMarkup.js',
        makeRequire({ './ticketKeyShapes.js': ticketKeyShapesModule }));

    test('flavorForTicket: Jira keys keep Jira wiki flavor', function () {
        assert.equal(commentMarkup.flavorForTicket('PROJ-74'), 'jira');
        assert.equal(commentMarkup.flavorForTicket('ABC-123'), 'jira');
        assert.equal(commentMarkup.flavorForTicket(null), 'jira');
    });

    test('flavorForTicket: GitHub key shapes select markdown', function () {
        assert.equal(commentMarkup.flavorForTicket('gh-122'), 'markdown');
        assert.equal(
            commentMarkup.flavorForTicket('epam/dmtools-dart#122'), 'markdown');
        assert.equal(commentMarkup.flavorForTicket('#122'), 'markdown');
        assert.equal(commentMarkup.flavorForTicket('122'), 'markdown');
    });

    test('flavorForTicket: customParams.commentMarkup overrides detection', function () {
        assert.equal(
            commentMarkup.flavorForTicket('PROJ-74', { commentMarkup: 'markdown' }),
            'markdown');
        assert.equal(
            commentMarkup.flavorForTicket('PROJ-74', { commentMarkup: 'github' }),
            'markdown');
        assert.equal(
            commentMarkup.flavorForTicket('gh-122', { commentMarkup: 'jira' }),
            'jira');
    });

    test('jira flavor renders the historical constructs byte-identically', function () {
        var m = commentMarkup.forTicket('PROJ-74');
        assert.equal(m.h(3, 'Development Completed'), 'h3. Development Completed');
        assert.equal(m.bold('Branch:'), '*Branch:*');
        assert.equal(m.code('ai/gh-122'), '{code}ai/gh-122{code}');
        assert.equal(m.code('x = 1', 'dart'), '{code:dart}x = 1{code}');
        assert.equal(
            m.link('PR #124', 'https://example.invalid/pull/124'),
            '[PR #124|https://example.invalid/pull/124]');
        assert.equal(
            m.panel('Note', 'body'),
            '{panel:title=Note}body\n{panel}');
    });

    test('markdown flavor renders GitHub-readable constructs', function () {
        var m = commentMarkup.forTicket('gh-122');
        assert.equal(m.h(3, 'Development Completed'), '### Development Completed');
        assert.equal(m.bold('Branch:'), '**Branch:**');
        assert.equal(m.code('ai/gh-122'), '```\nai/gh-122\n```');
        assert.equal(m.code('x = 1', 'dart'), '```dart\nx = 1\n```');
        assert.equal(
            m.link('PR #124', 'https://example.invalid/pull/124'),
            '[PR #124](https://example.invalid/pull/124)');
        assert.equal(
            m.panel('Note', 'body'),
            '> **Note**\n>\n> body');
    });

    test('forFlavor maps unknown values to jira (safe default)', function () {
        var m = commentMarkup.forFlavor('whatever');
        assert.equal(m.h(2, 'x'), 'h2. x');
    });

    test('inline renders a single-line code span for use inside bullets (gh-799)', function () {
        // m.code() renders a fenced BLOCK in the markdown flavor — inside a
        // bullet-list line it breaks the layout onto separate lines. Thread
        // ids/paths in the rework completion comment need an INLINE code span.
        var md = commentMarkup.forFlavor('markdown');
        assert.equal(md.inline('PRRT_abc'), '`PRRT_abc`');
        assert.equal(md.inline('src/a.dart:12'), '`src/a.dart:12`');
        assert.notContains(md.inline('x'), '\n', 'inline span must stay on one line');

        var jm = commentMarkup.forFlavor('jira');
        assert.equal(jm.inline('PRRT_abc'), '{code}PRRT_abc{code}');
    });

    test('flavor detection derives from the shared ticketKeyShapes owner (gh-770)', function () {
        // Swap in a shared owner that accepts NO shapes: a GitHub-shaped key
        // must then fall back to the jira flavor — proving there is no local
        // shape copy left behind in commentMarkup.
        var emptyShapes = {
            GITHUB_KEY_SHAPES: [],
            isGitHubKeyShape: function () { return false; },
            githubIssueNumberIn: function () { return null; },
            shapeSources: function () { return []; }
        };
        var isolated = loadModule('js/common/commentMarkup.js',
            makeRequire({ './ticketKeyShapes.js': emptyShapes }));
        assert.equal(isolated.flavorForTicket('gh-122'), 'jira');
        assert.equal(isolated.flavorForTicket('acme/w#12'), 'jira');
    });
});

suite('commentMarkup: branch names render inline on every flavor (agents#820)', function() {
    test('markdown inline() is a single-line backtick span (no fenced block, no newlines)', function() {
        var shapes = loadModule('js/common/ticketKeyShapes.js');
        var cm = loadModule('js/common/commentMarkup.js', makeRequire({ './ticketKeyShapes.js': shapes }));
        var m = cm.forFlavor('markdown');
        assert.equal(m.inline('feature/2023979-rate-limit'), '`feature/2023979-rate-limit`');
        assert.equal(m.inline('x').indexOf('\n'), -1);
    });
    test('the rework/PR comments put the branch inline, never in a fenced block', function() {
        var fs = ['js/preCliReworkSetup.js', 'js/pushReworkChanges.js', 'js/postTestReworkResults.js',
                  'js/developTicketAndCreatePR.js', 'js/preparePRForReview.js'];
        fs.forEach(function(f) {
            var src = file_read({ path: f });
            assert.equal(/m\.code\((ctx\.)?branchName/.test(src), false, f + ' renders the branch as a fenced block');
        });
    });
});

